UPDATE personal_match_participant
SET
    status = #{status},
    cancelled_at = NOW()
WHERE personal_match_id = #{personalMatchId}
	AND user_id = #{userId}

UPDATE personal_match_participant
SET
    attendance = #{attendance}
WHERE personal_match_id = #{personalMatchId}
	AND user_id = #{userId}

mapper.select:
SELECT *
FROM personal_match_participant
WHERE user_id = #{userId}
  AND personal_match_id = #{personalMatchId}
  AND status='결제완료'
